package co.caudal.application.device.command;

import java.time.Instant;
import java.util.UUID;

/**
 * A valve command to store as {@code PENDING} (docs/Protocolo-de-dispositivos.md, section 5.1). A
 * command has either a schedule item (generated by a published schedule) or a manual reason.
 *
 * @param aqueductId the aqueduct that owns it
 * @param deviceId the actuator that receives it
 * @param valveId the valve it moves
 * @param command OPEN or CLOSE
 * @param scheduleItemId the schedule item that originates it, or null for a manual command
 * @param manualReason the reason of a manual command, or null
 * @param createdBy the user who created it, or null when the system did
 * @param notBefore the command must not run before this moment
 * @param expiresAt the command must not run from this moment on
 */
public record NewValveCommand(
    UUID aqueductId,
    UUID deviceId,
    UUID valveId,
    String command,
    UUID scheduleItemId,
    String manualReason,
    UUID createdBy,
    Instant notBefore,
    Instant expiresAt) {}
